  ('a4-lugia', 'A4-238', 0.0042160536::numeric, 'Derived from Wisdom of Sea and Sky: Lugia Offering Rates and Limitless pack-filtered card availability; includes regular, regular-plus-bonus, and rare pack paths; cards A4-212 through A4-231 use shiny_1 rates and cards A4-232 through A4-239 use shiny_2 rates; probability means at least once per opened pack.', date '2026-06-24'),
  ('a4-lugia', 'A4-240', 0.0009993401::numeric, 'Derived from Wisdom of Sea and Sky: Lugia Offering Rates and Limitless pack-filtered card availability; includes regular, regular-plus-bonus, and rare pack paths; cards A4-212 through A4-231 use shiny_1 rates and cards A4-232 through A4-239 use shiny_2 rates; probability means at least once per opened pack.', date '2026-06-24'),
  ('a4-lugia', 'A4-241', 0.0010602362::numeric, 'Derived from Wisdom of Sea and Sky: Lugia Offering Rates and Limitless pack-filtered card availability; includes regular, regular-plus-bonus, and rare pack paths; cards A4-212 through A4-231 use shiny_1 rates and cards A4-232 through A4-239 use shiny_2 rates; probability means at least once per opened pack.', date '2026-06-24')
on conflict (pack_id, card_id) do update set
  pull_probability = excluded.pull_probability,
  source_note = excluded.source_note,
  verified_at = excluded.verified_at,
  updated_at = now();

-- Stop and roll back if the catalog, packs, or generated odds are incomplete.
do $$
declare
  wisdom_cards integer;
  wisdom_packs integer;
  wisdom_odds integer;
begin
  select count(*)
  into wisdom_cards
  from public.cards
  where set_id = 'A4';

  select count(*)
  into wisdom_packs
  from public.packs
  where set_id = 'A4';

  select count(*)
  into wisdom_odds
  from public.card_pack_odds
  where pack_id in ('a4-ho-oh', 'a4-lugia');

  if wisdom_cards <> 241 then
    raise exception
      'Expected 241 Wisdom of Sea and Sky cards, found %',
      wisdom_cards;
  end if;

  if wisdom_packs <> 2 then
    raise exception
      'Expected 2 Wisdom of Sea and Sky packs, found %',
      wisdom_packs;
  end if;

  if wisdom_odds <> 272 then
    raise exception
      'Expected 272 Wisdom of Sea and Sky odds rows, found %',
      wisdom_odds;
  end if;
end
$$;

commit;

-- Expected: 272 total records across the two Wisdom of Sea and Sky packs.
select
  card_pack_odds.pack_id,
  cards.rarity,
  count(*) as cards,
  min(card_pack_odds.pull_probability) as min_pull_probability,
  max(card_pack_odds.pull_probability) as max_pull_probability
from public.card_pack_odds
join public.cards
  on cards.id = card_pack_odds.card_id
where card_pack_odds.pack_id in ('a4-ho-oh', 'a4-lugia')
group by card_pack_odds.pack_id, cards.rarity
order by card_pack_odds.pack_id, min(cards.collector_number);
